<script module lang="ts">
/**
 * The records screen (`design/archetypes/list-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { Render, joinSlot } from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/archetypes/list-page.module.css'
import EmptyState from '../structure/EmptyState.svelte'
import Inline from '../layout/Inline.svelte'
import PageHeader from '../structure/PageHeader.svelte'
import type { EmptyStateProps } from '../structure/EmptyState.svelte'

export interface ListPageProps {
  /**
   * Vocabulary controls, including the page's one primary action.
   */
  actions?: Snippet
  /**
   * A Table composition.
   */
  children: Snippet
  description?: string
  empty?: boolean
  /**
   * The empty state, required so the page always defines what it shows with no records.
   */
  emptyState: EmptyStateProps
  /**
   * `sm` controls by convention, and never a solid Button.
   */
  filters?: Snippet
  /**
   * The band above the filters (the dashboard block's section cards), with the page's key
   * numbers. By convention it is a `Grid` of Stats in Cards. It is a slot, not part of
   * `children`, because of a law. The body is a panel with Card's surface recipe, and cards do
   * not nest, so stat cards inside it would be boxes inside a box. It also stays in place during
   * the body swap, because a filter that matches nothing does not change how many tickets are
   * open.
   */
  summary?: Snippet
  title: string
}
</script>

<script lang="ts">
let {
  actions,
  children,
  description,
  empty = false,
  emptyState,
  filters,
  summary,
  title,
}: ListPageProps = $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get actions() {
    return actions
  },
  get default() {
    return children
  },
  get filters() {
    return filters
  },
  get summary() {
    return summary
  },
}
let nothing = $state<HTMLElement | null>(null)
let records = $state<HTMLElement | null>(null)
const recordsPresent = usePresence(
  () => !empty,
  () => records,
  'listpage.bodyswap',
)
const emptyPresent = usePresence(
  () => empty,
  () => nothing,
  'listpage.bodyswap',
)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.page} data-empty={(empty) ? '' : undefined} data-member="list-page"
    >{#snippet actionsOfPageHeader1()}{@render actions?.()}{/snippet
    }<PageHeader {title} {description} actions={slots.actions ? actionsOfPageHeader1 : undefined}
    />{@render summary?.()
    }{#if slots.filters}<Inline gap={3} wrap={true}>{@render filters?.()}</Inline>{/if
    }<div class={styles.bodySlot}
      >{#if recordsPresent.current
        }<div bind:this={records} class={styles.body}>{@render children?.()}</div
      >{/if
      }{#if emptyPresent.current
        }<div bind:this={nothing} class={styles.body}
          >{#snippet actionOfEmptyState2()}<Render node={emptyState.action} />{/snippet
          }{#snippet secondaryActionOfEmptyState3()
            }<Render node={emptyState.secondaryAction}
          />{/snippet
          }<EmptyState
            icon={emptyState.icon}
            title={emptyState.title}
            description={emptyState.description}
            action={emptyState.action !== undefined ? actionOfEmptyState2 : undefined}
            secondaryAction={emptyState.secondaryAction !== undefined ? secondaryActionOfEmptyState3 : undefined}
        /></div
      >{/if
    }</div
  ></div
>{/if
}{@render joined.end?.()}
